import type { Sex, Zone } from "./proesp";

export const WHO_BMI_MIN_MONTHS = 61;
export const WHO_BMI_MAX_MONTHS = 228;

export interface WhoBmiMonthCuts {
  m: number;      // Mês completo (61..228)
  L: number;
  M: number;
  S: number;
  sd3neg: number; // Escore-z = -3
  sd2neg: number; // Escore-z = -2
  sd1neg: number; // Escore-z = -1
  sd0: number;    // Escore-z = 0 (mediana)
  sd1: number;    // Escore-z = +1
  sd2: number;    // Escore-z = +2
  sd3: number;    // Escore-z = +3
}

export type WhoBmiCategory =
  | "magreza acentuada"
  | "magreza"
  | "eutrofia"
  | "sobrepeso"
  | "obesidade"
  | "obesidade grave";

export const WHO_BMI_CATEGORIES: WhoBmiCategory[] = [
  "magreza acentuada",
  "magreza",
  "eutrofia",
  "sobrepeso",
  "obesidade",
  "obesidade grave",
];

export const WHO_BMI_CATEGORY_LABEL: Record<WhoBmiCategory, string> = {
  "magreza acentuada": "Magreza Acentuada",
  "magreza": "Magreza",
  "eutrofia": "Eutrofia",
  "sobrepeso": "Sobrepeso",
  "obesidade": "Obesidade",
  "obesidade grave": "Obesidade Grave",
};

/**
 * Mapeamento da classificação z-score do IMC da OMS 2007 para a zona interna da dimensão Saúde Corporal.
 * [PENDENTE DE DECISÃO TÉCNICA] Mapeamento mantido conforme histórico do sistema para preservar a pontuação dimensional,
 * sem arbitrar novos valores.
 */
export const WHO_BMI_TO_HEALTH_ZONE_MAP: Record<WhoBmiCategory, Zone> = {
  "magreza acentuada": "Muito Fraco",
  "magreza": "Fraco",
  "eutrofia": "Excelente",
  "sobrepeso": "Razoável",
  "obesidade": "Fraco",
  "obesidade grave": "Muito Fraco",
};

export const WHO_BMI_DISCLAIMER =
  "O IMC é uma ferramenta de triagem populacional e acompanhamento do crescimento, não constituindo diagnóstico clínico isolado.";

export function whoBmiFamilyGuidance(cat: WhoBmiCategory, studentName?: string): string {
  const name = studentName || "O(A) estudante";
  switch (cat) {
    case "magreza acentuada":
    case "magreza":
      return `${name} apresenta índice abaixo da faixa de referência para a idade. Recomendamos acompanhamento de rotina com profissional de saúde para avaliar o crescimento corporal e assegurar aportes nutricionais adequados.`;
    case "eutrofia":
      return `${name} apresenta índice em faixa compatível com o crescimento saudável para a idade. Mantenha os hábitos ativos e a alimentação variada.`;
    case "sobrepeso":
      return `${name} apresenta índice acima da faixa de referência para a idade. O incentivo a brincadeiras ativas e redução do tempo sedentário são ótimos aliados para o desenvolvimento motor.`;
    case "obesidade":
    case "obesidade grave":
      return `${name} apresenta índice significativamente acima do esperado para a idade. Sugerimos acompanhamento com profissional de saúde e apoio familiar no estímulo a práticas prazerosas de movimento diário.`;
  }
}

