export function getWhoBmiCuts(sex: Sex, ageMonths: number): WhoBmiMonthCuts | null {
  if (ageMonths < WHO_BMI_MIN_MONTHS || ageMonths > WHO_BMI_MAX_MONTHS) {
    return null;
  }
  const table = sex === "female" ? WHO_BMI_GIRLS : WHO_BMI_BOYS;
  return table[ageMonths] ?? null;
}

/**
 * Classifica o IMC conforme os valores exatos de escore-z da OMS 2007 para a idade em meses completos:
 * - < -3: magreza acentuada
 * - -3 a < -2: magreza
 * - -2 a +1: eutrofia
 * - > +1 a +2: sobrepeso
 * - > +2 a +3: obesidade
 * - > +3: obesidade grave
 * Fora de 61..228 meses: retorna null (sem referência oficial).
 */
export function classifyWhoBmi(
  imc: number | null | undefined,
  sex: Sex,
  ageMonths: number | null | undefined,
): WhoBmiCategory | null {
  if (imc == null || ageMonths == null) return null;
  const cuts = getWhoBmiCuts(sex, ageMonths);
  if (!cuts) return null;

  if (imc < cuts.sd3neg) return "magreza acentuada";
  if (imc < cuts.sd2neg) return "magreza";
  if (imc <= cuts.sd1) return "eutrofia";
  if (imc <= cuts.sd2) return "sobrepeso";
  if (imc <= cuts.sd3) return "obesidade";
  return "obesidade grave";
}

/**
 * Faixa esperada do cartão clínico para o IMC:
 * Limite inferior: z = -2 (cuts.sd2neg)
 * Limite superior: z = +1 (cuts.sd1)
 * Limites totais do domínio (gráfico): z = -3 a z = +3.
 */
export function getWhoBmiExpectedRange(
  sex: Sex,
  ageMonths: number | null | undefined,
): { min: number; max: number; domainMin: number; domainMax: number; higherBetter: boolean } | null {
  if (ageMonths == null) return null;
  const cuts = getWhoBmiCuts(sex, ageMonths);
  if (!cuts) return null;

  return {
    min: cuts.sd2neg,
    max: cuts.sd1,
    domainMin: cuts.sd3neg,
    domainMax: cuts.sd3,
    higherBetter: false,
  };
}
